{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 주차장 융자를 받은 사람의 최소 운영기간 기준",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "융자를 받은 사람은 융자금의 상환기간 이상 주차장을 운영하여야 한다. 따라서 최소 운영기간 기준은 융자금의 상환기간이다.",
          "b_ids": "주차장:제26조제4항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "도시계획정비사업 때문에 노외주차장 용도가 바뀌는 경우가 융자 즉시 반환 사유에 해당하는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "상환기간 중에 노외주차장의 용도가 변경되거나 소멸된 때는 즉시 반환 사유에 해당한다. 다만 도시계획정비사업 등 불가피한 사유의 용도변경 및 소멸은 예외로 한다. 따라서 도시계획정비사업 때문에 노외주차장 용도가 바뀌는 경우는 즉시 반환 사유로 보지 않는다.",
          "b_ids": "주차장:제28조, 주차장:제28조제2호, 주차장:제28조제2호단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
